package vn.rtr.aeris.workbench02;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import android.system.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.*;import java.util.*;import java.util.concurrent.*;
/** Isolated host-companion mock shell. No flight driver, no authority restore. */
public final class ShellActivity extends Activity {
 private static final String ORIGIN="http://127.0.0.1:8892";private final String instance=UUID.randomUUID().toString();private volatile String session=UUID.randomUUID().toString();private volatile boolean foreground=false,destroyed=false;private boolean busy=false,pickerOwned=false;private long lastSequence=0;private WebView web;private WorkspaceStore store;private final ExecutorService io=Executors.newSingleThreadExecutor();private JSONObject pending;private byte[] exportBytes;private String exportSha;
 private JSONObject obj(Object...kv)throws Exception{JSONObject r=new JSONObject();for(int i=0;i<kv.length;i+=2)r.put((String)kv[i],kv[i+1]);return r;}
 private static boolean origin(String url){try{URI u=new URI(url);return "http".equals(u.getScheme())&&"127.0.0.1".equals(u.getHost())&&u.getPort()==8892&&u.getUserInfo()==null;}catch(Exception e){return false;}}
 private void directorySync(File dir)throws IOException{try{java.io.FileDescriptor fd=Os.open(dir.getPath(),OsConstants.O_RDONLY,0);try{Os.fsync(fd);}finally{Os.close(fd);}}catch(Exception e){throw new IOException("DIRECTORY_FSYNC",e);}}
 @Override public void onCreate(Bundle b){super.onCreate(b);try{store=new WorkspaceStore(new File(getFilesDir(),"workbench02"),this::directorySync,p->{});}catch(Exception e){fatal(e);return;}web=new WebView(this);web.setBackgroundColor(0xff101719);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setGeolocationEnabled(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setSupportMultipleWindows(false);s.setSaveFormData(false);web.addJavascriptInterface(new Broker(),"NativeWB02");
  web.setWebViewClient(new WebViewClient(){@Override public void onPageStarted(WebView w,String u,android.graphics.Bitmap icon){session=UUID.randomUUID().toString();lastSequence=0;}@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !origin(r.getUrl().toString());}@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){if(origin(r.getUrl().toString()))return null;return new WebResourceResponse("text/plain","UTF-8",403,"Origin blocked",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}});web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]>cb,FileChooserParams p){cb.onReceiveValue(null);return true;}});web.setDownloadListener((a,c,d,e,f)->Toast.makeText(this,"Dùng xuất SAF có kiểm SHA.",Toast.LENGTH_LONG).show());web.loadUrl(ORIGIN+"/");
 }
 private void fatal(Exception e){TextView t=new TextView(this);t.setPadding(24,24,24,24);t.setText("Workbench02 không mở dữ liệu: "+e.getMessage()+"\nKhông có quyền điều khiển được khôi phục.");setContentView(t);}
 public final class Broker{
  @JavascriptInterface public String environment(){try{return obj("format","aeris-native-workbench02","platform","ANDROID","instance",instance,"session",session,"foreground",foreground).toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public void request(String raw){if(raw==null||raw.getBytes(StandardCharsets.UTF_8).length>3145728)return;runOnUiThread(()->{JSONObject q=null;try{q=new JSONObject(raw);if(q.length()!=6||(!(q.opt("version") instanceof Number)||((Number)q.opt("version")).doubleValue()!=1)||!instance.equals(q.getString("instance"))||!session.equals(q.getString("session"))||!foreground||destroyed||!origin(web.getUrl()))throw new IOException("NATIVE_CONTEXT_REFUSED");String requestId=q.getString("id"),prefix=instance+":";if(!requestId.startsWith(prefix)||!requestId.substring(prefix.length()).matches("[1-9][0-9]{0,8}"))throw new IOException("NATIVE_REQUEST_ID");long seq=Long.parseLong(requestId.substring(prefix.length()));if(seq<=lastSequence)throw new IOException("NATIVE_REQUEST_REPLAY");if(busy)throw new IOException("NATIVE_BUSY_NO_QUEUE");String action=q.getString("action");if(!Arrays.asList("load","save","export","pick-json","pick-kml").contains(action))throw new IOException("NATIVE_ACTION_REFUSED");busy=true;lastSequence=seq;JSONObject request=q;io.execute(()->perform(request));}catch(Exception e){deliver(q,null,e,false);}});}
 }
 private void verifyContext(JSONObject q)throws Exception{if(!foreground||destroyed||!session.equals(q.getString("session")))throw new IOException("NATIVE_FOREGROUND_LOST");}
 private byte[] utf8(String text)throws Exception{byte[]b=text.getBytes(StandardCharsets.UTF_8);if(b.length>WorkspaceStore.MAX_BODY)throw new IOException("BODY_BOUND");return b;}
 private void validateBody(byte[]body)throws Exception{
  JSONObject bundle=new JSONObject(new String(body,StandardCharsets.UTF_8));if(!bundle.getString("format").equals("aeris-workbench01-workspace")||bundle.getInt("version")!=1||bundle.getBoolean("operational")||bundle.getBoolean("authorityRestorable"))throw new IOException("WORKSPACE_SCOPE");
  HttpURLConnection c=(HttpURLConnection)new URL(ORIGIN+"/api/native/validate").openConnection();try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(3000);c.setReadTimeout(5000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Origin",ORIGIN);c.setRequestProperty("Content-Type","application/json");byte[]request=obj("body",new String(body,StandardCharsets.UTF_8)).toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(request.length);try(OutputStream o=c.getOutputStream()){o.write(request);}if(c.getResponseCode()!=200)throw new IOException("HOST_SEMANTIC_REFUSED");JSONObject receipt;try(InputStream in=c.getInputStream()){receipt=new JSONObject(new String(WorkspaceStore.read(in,8192),StandardCharsets.UTF_8));}if(!receipt.getBoolean("ok")||!receipt.getString("bodySha256").equals(WorkspaceStore.sha(body))||receipt.getBoolean("authorityRestorable"))throw new IOException("HOST_RECEIPT_SHA_SCOPE");}finally{c.disconnect();}
 }
 private JSONObject snapshot(WorkspaceStore.Snapshot s)throws Exception{return obj("status",s.status,"head",s.head,"body",s.body==null?JSONObject.NULL:s.body,"bodySha256",s.sha==null?JSONObject.NULL:s.sha,"platform","ANDROID","authorityRestored",false);}
 private void perform(JSONObject q){try{verifyContext(q);String action=q.getString("action");JSONObject a=q.getJSONObject("args"),result;
  if(action.equals("load")){result=snapshot(store.load());reply(q,result,null);return;}
  if(action.equals("save")||action.equals("export")){byte[]b=utf8(a.getString("body"));String digest=WorkspaceStore.sha(b);if(!digest.equals(a.getString("bodySha256")))throw new IOException("BODY_SHA");validateBody(b);verifyContext(q);if(action.equals("save")){String old=a.getString("expectedHead");result=snapshot(store.save(old,new String(b,StandardCharsets.UTF_8)));result.put("previousHead",old);reply(q,result,null);return;}exportBytes=b;exportSha=digest;}
  pending=q;runOnUiThread(()->{try{verifyContext(q);pickerOwned=true;Intent intent=new Intent(action.equals("export")?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(action.equals("pick-kml")?"*/*":"application/json");if(action.equals("export"))intent.putExtra(Intent.EXTRA_TITLE,"AERIS-workbench02-workspace.json");startActivityForResult(intent,2202);}catch(Exception e){pickerOwned=false;pending=null;exportBytes=null;reply(q,null,e);}});
 }catch(Exception e){reply(q,null,e);}}
 private void reply(JSONObject q,JSONObject result,Exception error){deliver(q,result,error,true);}
 private void deliver(JSONObject q,JSONObject result,Exception error,boolean release){runOnUiThread(()->{if(release)busy=false;if(q==null||web==null||destroyed||!origin(web.getUrl()))return;try{JSONObject r=obj("version",1,"id",q.optString("id"),"instance",q.optString("instance"),"session",q.optString("session"),"action",q.optString("action"),"ok",error==null);if(error==null)r.put("result",result);else r.put("error",error.getMessage());web.evaluateJavascript("window.nativeWB02Reply&&window.nativeWB02Reply(JSON.parse("+JSONObject.quote(r.toString())+"))",null);}catch(Exception ignored){}});}
 @Override protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(req!=2202)return;JSONObject q=pending;pending=null;pickerOwned=false;if(q==null)return;if(code!=RESULT_OK||data==null||data.getData()==null){exportBytes=null;reply(q,null,new IOException("SAF_CANCELLED_NO_SUCCESS"));return;}Uri uri=data.getData();byte[]bytes=exportBytes;String expected=exportSha;exportBytes=null;io.execute(()->{try{if(!session.equals(q.getString("session"))||destroyed)throw new IOException("SAF_DOCUMENT_SESSION_CHANGED");String action=q.getString("action");JSONObject r;if(action.equals("export")){if(bytes==null)throw new IOException("SAF_PENDING_BYTES_LOST");try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("SAF_OUTPUT_NULL");out.write(bytes);out.flush();}byte[]readback;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("SAF_READBACK_NULL");readback=WorkspaceStore.read(in,WorkspaceStore.MAX_BODY);}if(!WorkspaceStore.sha(readback).equals(expected)||readback.length!=bytes.length)throw new IOException("SAF_READBACK_MISMATCH_UNKNOWN_WRITE");r=obj("status","SAF_READBACK_VERIFIED","bodySha256",expected,"bytes",bytes.length);}else{byte[]b;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("SAF_INPUT_NULL");b=WorkspaceStore.read(in,action.equals("pick-kml")?262144:WorkspaceStore.MAX_BODY);}String body=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();if(action.equals("pick-json"))validateBody(b);r=obj("status","PICK_READ_VERIFIED","body",body,"bodySha256",WorkspaceStore.sha(b));}r.put("platform","ANDROID");r.put("authorityRestored",false);reply(q,r,null);}catch(Exception e){deliver(q,null,e,false);}});}
 @Override protected void onResume(){super.onResume();foreground=true;}
 @Override protected void onPause(){foreground=false;if(web!=null)web.evaluateJavascript("window.dispatchEvent(new CustomEvent('wb-native-background',{detail:{pickerOwned:"+pickerOwned+"}}));",null);super.onPause();}
 @Override protected void onDestroy(){destroyed=true;foreground=false;io.shutdown();if(web!=null){web.removeJavascriptInterface("NativeWB02");web.destroy();}super.onDestroy();}
}
